const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const assetId = String($json.asset_id ?? '').trim();
if (!uuidPattern.test(contentId)) {
  throw new Error('Fetch Next Approval Candidate did not produce a valid content_id.');
}
if (!uuidPattern.test(assetId)) {
  throw new Error('Fetch Next Approval Candidate did not produce a valid asset_id.');
}
if (!String($json.caption_final ?? '').trim()) {
  throw new Error('Fetch Next Approval Candidate did not produce caption_final.');
}
if (!String($json.storage_url ?? '').trim()) {
  throw new Error('Fetch Next Approval Candidate did not produce storage_url.');
}
const metadata = $json.metadata_json ?? {};
const assetPreviewUrl = String(metadata.generated_url ?? '').trim() || String($json.source_url ?? '').trim() || String($json.storage_url ?? '').trim();
return [{
  json: {
    ...$json,
    workflow_name: 'wf_content_approval',
    run_started_at: new Date().toISOString(),
    review_summary: {
      title: String($json.title ?? '').trim(),
      category: String($json.category ?? '').trim(),
      selected_hook: String($json.selected_hook ?? '').trim(),
      caption_final: String($json.caption_final ?? '').trim(),
      hashtags_final: String($json.hashtags_final ?? '').trim(),
      asset_preview_url: assetPreviewUrl,
      asset_delivery_url: String($json.storage_url ?? '').trim(),
      asset_provider: String($json.provider ?? '').trim(),
      asset_status: String($json.asset_status ?? '').trim()
    }
  }
}];

return [{
  json: {
    ...$json,
    approval_decision: 'approve',
    review_note: 'Approved after manual review in wf_content_approval.'
  }
}];

const decision = String($json.approval_decision ?? '').trim().toLowerCase();
if (!['approve', 'reject'].includes(decision)) {
  throw new Error('Manual Approval Decision must set approval_decision to approve or reject.');
}
const note = String($json.review_note ?? '').trim();
if (!note) {
  throw new Error('Manual Approval Decision must include a non-empty review_note.');
}
return [{
  json: {
    ...$json,
    approval_decision: decision,
    review_note: note,
    next_content_status: decision === 'approve' ? 'qa_approved' : 'approval_rejected',
    next_asset_status: decision === 'approve' ? 'ready' : 'rejected',
    approved_by_human: decision === 'approve'
  }
}];

const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const contentId = String($json.content_id ?? '').trim();
const assetId = String($json.asset_id ?? '').trim();
if (!uuidPattern.test(contentId) || !uuidPattern.test(assetId)) {
  throw new Error('Normalize Approval Decision produced an invalid content_id or asset_id.');
}
const startedAt = new Date(String($json.run_started_at ?? new Date().toISOString()));
const durationMs = Math.max(0, Date.now() - startedAt.getTime());
return [{
  json: {
    ...$json,
    content_id_sql: contentId,
    asset_id_sql: assetId,
    workflow_name_sql: String($json.workflow_name ?? 'wf_content_approval').replaceAll("'", "''"),
    approval_decision_sql: String($json.approval_decision ?? '').replaceAll("'", "''"),
    review_note_sql: String($json.review_note ?? '').replaceAll("'", "''"),
    next_content_status_sql: String($json.next_content_status ?? '').replaceAll("'", "''"),
    next_asset_status_sql: String($json.next_asset_status ?? '').replaceAll("'", "''"),
    review_summary_json_sql: JSON.stringify($json.review_summary ?? {}).replaceAll("'", "''"),
    duration_ms_sql: Number.isFinite(durationMs) ? durationMs : 0
  }
}];
